// 데모 모드 전용 로그인 API mock

export const LoginAPI = async (param) => {
  // param에는 { loginId, password }
  // 여기선 무조건 성공 반환.
  // slice는 { success, name, message } 를 기대하고 있음.

  return {
    success: true,
    name: param?.loginId || "데모사용자",
    message: "데모 로그인 완료 (백엔드 없음)",
  };
};

// 로그아웃도 같이 준비
export const logout = async () => {
  return { success: true };
};
